  width: 18px;
  height: 18px;
  fill: #7a7a9e;
}
.nav-links {
  display: flex;
  gap: 24px;
  align-items: center;
}
.nav-links a {
  color: #fff;
  font-size: 0.95rem;
  font-weight: 500;
  text-decoration: none;
  transition: color 0.2s;
}
.nav-links a:hover { color: #FEAC32; text-decoration: none; }

/* Hamburger */
.hamburger {
  display: none;
  background: none;
  border: none;
  color: #fff;
  width: 44px;
  height: 44px;
  align-items: center;
  justify-content: center;
}
.hamburger svg { width: 26px; height: 26px; stroke: #fff; fill: none; stroke-width: 2; stroke-linecap: round; }

/* Mobile nav */
.mobile-nav {
  display: none;
  background: #0a0a23;
  border-top: 1px solid #1b1b36;
  padding: 16px 24px;
}
.mobile-nav.open { display: block; }
.mobile-nav a {
  display: block;
  color: #fff;
  font-size: 1rem;
  font-weight: 500;
  padding: 12px 0;
  text-decoration: none;
  border-bottom: 1px solid #1b1b36;
  transition: color 0.2s;
}
.mobile-nav a:last-child { border-bottom: none; }
.mobile-nav a:hover { color: #FEAC32; text-decoration: none; }

@media (max-width: 768px) {
  .nav-links { display: none; }
  .hamburger { display: flex; }
  .search-bar { max-width: 200px; }
  .search-bar input { font-size: 0.8rem; padding: 8px 12px 8px 36px; }
}
@media (max-width: 480px) {
  .search-bar { display: none; }
  .header-top { padding: 12px 16px; }
}

/* ===== Banner ===== */
.banner {
  background: #002EAD;
  color: #fff;
  text-align: center;
  padding: 12px 24px;
  font-size: 0.95rem;
  font-weight: 600;
  letter-spacing: 0.01em;
}
.banner a { color: #FEAC32; font-weight: 700; }

/* ===== Featured Article ===== */
.featured {
  padding: 48px 0 32px;
}
.featured-card {
  position: relative;
  border-radius: 12px;
  overflow: hidden;
  background: #1a1a2e;
  min-height: 360px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  color: #fff;
}
.featured-card .featured-img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0.55;
}
.featured-card .featured-overlay {
  position: relative;
  z-index: 1;
  padding: 40px 32px;
  max-width: 720px;
}
.tag-label {
  display: inline-block;
  background: #FEAC32;
  color: #0a0a23;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 4px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-bottom: 12px;
}
.tag-label--ai { background: #FEAC32; }
.tag-label--web-scraping { background: #3b82f6; color: #fff; }
.tag-label--databases { background: #10b981; color: #fff; }
.tag-label--elasticsearch { background: #8b5cf6; color: #fff; }
.tag-label--data-engineering { background: #f59e0b; }
.tag-label--python { background: #3b82f6; color: #fff; }
.tag-label--node-js { background: #22c55e; color: #fff; }
.tag-label--google-sheets { background: #16a34a; color: #fff; }
.tag-label--ai-automation { background: #ec4899; color: #fff; }
.featured-card h2 {
  font-size: 1.75rem;
  font-weight: 700;
  line-height: 1.3;
  margin-bottom: 16px;
}
.author-row {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 0.85rem;
  color: rgba(255,255,255,0.85);
}
.author-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: #2a2a4a;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: 700;
  color: #FEAC32;
  flex-shrink: 0;
}

/* ===== Article Grid ===== */
.section-title {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 24px;
  color: #0a0a23;
}
.article-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  padding-bottom: 32px;
}
@media (max-width: 900px) { .article-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 600px) { .article-grid { grid-template-columns: 1fr; } }

.article-card {
  background: #fff;
  border-radius: 10px;
  overflow: hidden;
  border: 1px solid #e5e7eb;
  transition: box-shadow 0.2s, transform 0.15s;
}
.article-card:hover {
  box-shadow: 0 8px 24px rgba(0,0,0,0.08);
  transform: translateY(-2px);
}
.card-thumb {
  width: 100%;
  height: 180px;
  background: linear-gradient(135deg, #1b1b36 0%, #2a2a4a 100%);
  position: relative;
  overflow: hidden;
}
.card-thumb-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0.6;
}
.card-thumb .tag-label {
  position: absolute;
  top: 12px;
  left: 12px;
  z-index: 1;
}
.card-body {
  padding: 16px 18px 18px;
}
.card-body h3 {
  font-size: 1.05rem;
  font-weight: 600;
  line-height: 1.4;
  margin-bottom: 12px;
  color: #0a0a23;
}
.card-body h3 a { color: inherit; text-decoration: none; }
.card-body h3 a:hover { color: #002EAD; text-decoration: underline; }
.card-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.82rem;
  color: #6b7280;
}
.card-meta .author-avatar { width: 26px; height: 26px; font-size: 0.65rem; }

/* Load More */
.load-more-wrap {
  text-align: center;
  padding: 16px 0 48px;
}
.btn-load-more {
  background: #0a0a23;
  color: #fff;
  border: none;
  padding: 14px 36px;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: 600;
  transition: background 0.2s;
}
.btn-load-more:hover { background: #1b1b36; }

/* ===== Learn Page ===== */
.welcome-cta {
  padding: 48px 0 24px;
  text-align: center;
}
.welcome-cta p {
  font-size: 1.15rem;
  color: #4b5563;
  max-width: 620px;
  margin: 0 auto;
}
.welcome-cta a { color: #002EAD; font-weight: 600; }

.curriculum-section {
  padding: 32px 0;
}
.curriculum-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 16px;
}
.curriculum-card {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 20px;
  border: 1px solid #e5e7eb;
  border-radius: 10px;
  transition: box-shadow 0.2s, border-color 0.2s;
  text-decoration: none;
  color: inherit;
}
.curriculum-card:hover {
  box-shadow: 0 4px 16px rgba(0,0,0,0.06);
  border-color: #002EAD;
  text-decoration: none;
}
.curriculum-icon {
  width: 48px;
  height: 48px;
  border-radius: 10px;
  background: #f0f4ff;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: 1.3rem;
}
.curriculum-card h3 {
  font-size: 1rem;
  font-weight: 600;
  color: #0a0a23;
}
.curriculum-card p {
  font-size: 0.82rem;
  color: #6b7280;
  margin-top: 2px;
}

/* Daily Challenge */
.daily-challenge {
  padding: 32px 0;
}
.challenge-box {
  background: linear-gradient(135deg, #0a0a23 0%, #002EAD 100%);
  color: #fff;
  border-radius: 12px;
  padding: 40px;
  text-align: center;
}
.challenge-box h2 { font-size: 1.5rem; margin-bottom: 8px; }
.challenge-box p { color: rgba(255,255,255,0.8); margin-bottom: 20px; }
.challenge-links { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }
.challenge-links a {
  background: #FEAC32;
  color: #0a0a23;
  padding: 12px 24px;
  border-radius: 8px;
  font-weight: 600;
  text-decoration: none;
  transition: background 0.2s;
}
.challenge-links a:hover { background: #fbbf24; text-decoration: none; }
.challenge-links a.secondary {
  background: transparent;
  border: 2px solid rgba(255,255,255,0.4);
  color: #fff;
}
.challenge-links a.secondary:hover { border-color: #FEAC32; color: #FEAC32; }

/* Learn Subsections */
.learn-subsection {
  padding: 32px 0;
  border-top: 1px solid #e5e7eb;
}
.learn-subsection h2 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 16px;
  color: #0a0a23;
}
.learn-links {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}
.learn-links a {
  background: #f3f4f6;
  padding: 10px 20px;
  border-radius: 8px;
  color: #0a0a23;
  font-weight: 500;
  font-size: 0.9rem;
  text-decoration: none;
  transition: background 0.2s, color 0.2s;
}
.learn-links a:hover { background: #002EAD; color: #fff; text-decoration: none; }

/* ===== Donate Page ===== */
.donate-hero {
  padding: 56px 0 32px;
  text-align: center;
}
.donate-hero h1 {
  font-size: 2.25rem;
  font-weight: 800;
  color: #0a0a23;
  margin-bottom: 16px;
}
.donate-hero p {
  font-size: 1.1rem;
  color: #4b5563;
  max-width: 640px;
  margin: 0 auto;
  line-height: 1.7;
}

/* Donation Form */
.donation-form {
  padding: 40px 0;
}
.donation-card {
  background: #f9fafb;
  border-radius: 16px;
  padding: 40px;
  max-width: 560px;
  margin: 0 auto;
  text-align: center;
  border: 2px solid #e5e7eb;
}
.amount-tabs {
  display: flex;
  gap: 8px;
  justify-content: center;
  margin-bottom: 24px;
}
.amount-tab {
  background: #fff;
  border: 2px solid #e5e7eb;
  border-radius: 8px;
  padding: 12px 24px;
  font-size: 1.1rem;
  font-weight: 700;
  color: #0a0a23;
  transition: all 0.2s;
}
.amount-tab:hover { border-color: #002EAD; }
.amount-tab.active {
  background: #0a0a23;
  color: #FEAC32;
  border-color: #0a0a23;
}
.donation-desc {
  font-size: 1.05rem;
  color: #4b5563;
  margin-bottom: 24px;
  line-height: 1.6;
}
.btn-donate {
  background: #FEAC32;
  color: #0a0a23;
  border: none;
  padding: 16px 48px;
  border-radius: 8px;
  font-size: 1.1rem;
  font-weight: 700;
  transition: background 0.2s;
  display: inline-block;
}
.btn-donate:hover { background: #fbbf24; }
.donation-sub {
  font-size: 0.82rem;
  color: #9ca3af;
  margin-top: 12px;
}

/* Supporter Benefits */
.supporter-benefits {
  padding: 40px 0;
}
.supporter-benefits h2 {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 24px;
  text-align: center;
}
.benefits-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 16px;
}
.benefit-item {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 16px;
  background: #f9fafb;
  border-radius: 10px;
}
.benefit-icon {
  width: 36px;
  height: 36px;
  border-radius: 8px;
  background: #fef3c7;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: 1rem;
}
.benefit-item p {
  font-size: 0.92rem;
  color: #374151;
  line-height: 1.5;
}

/* Initiatives & Achievements */
.initiatives, .achievements {
  padding: 40px 0;
}
.initiatives h2, .achievements h2 {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 24px;
  text-align: center;
}
.initiative-list {
  max-width: 640px;
  margin: 0 auto;
}
.initiative-list li {
  padding: 12px 0;
  border-bottom: 1px solid #f3f4f6;
  font-size: 0.95rem;
  color: #374151;
  display: flex;
  align-items: center;
  gap: 10px;
}
.initiative-list li::before {
  content: '';
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #FEAC32;
  flex-shrink: 0;
}
.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 24px;
  text-align: center;
}
.stat-item h3 {
  font-size: 1.75rem;
  font-weight: 800;
  color: #0a0a23;
}
.stat-item p {
  font-size: 0.88rem;
  color: #6b7280;
  margin-top: 4px;
}

/* FAQ Accordion */
.faq-section {
  padding: 48px 0;
}
.faq-section h2 {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 24px;
  text-align: center;
}
.faq-list {
  max-width: 720px;
  margin: 0 auto;
}
.faq-item {
  border-bottom: 1px solid #e5e7eb;
}
.faq-question {
  width: 100%;
  background: none;
  border: none;
  padding: 18px 0;
  font-size: 1rem;
  font-weight: 600;
  color: #0a0a23;
  text-align: left;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  transition: color 0.2s;
}
.faq-question:hover { color: #002EAD; }
.faq-chevron {
  width: 20px;
  height: 20px;
  transition: transform 0.25s ease;
  flex-shrink: 0;
}
.faq-item.open .faq-chevron { transform: rotate(180deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}
.faq-item.open .faq-answer {
  max-height: 300px;
  padding-bottom: 18px;
}
.faq-answer p {
  font-size: 0.92rem;
  color: #6b7280;
  line-height: 1.7;
}

/* ===== Tag Page ===== */
.tag-header-section {
  padding: 48px 0 24px;
  text-align: center;
}
.tag-header-section h1 {
  font-size: 2rem;
  font-weight: 800;
  color: #0a0a23;
  margin-bottom: 8px;
}
.tag-header-section .tag-count {
  font-size: 1rem;
  color: #6b7280;
}

/* Popular Tags */
.popular-tags {
  padding: 16px 0 32px;
}
.popular-tags h3 {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 12px;
  color: #0a0a23;
}
.tags-row {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}
.tag-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 16px;
  background: #f3f4f6;
  border-radius: 20px;
  font-size: 0.85rem;
  font-weight: 500;
  color: #374151;
  text-decoration: none;
  transition: background 0.2s, color 0.2s;
}
.tag-chip:hover { background: #002EAD; color: #fff; text-decoration: none; }
.tag-chip .count {
  font-size: 0.75rem;
  color: #9ca3af;
}
.tag-chip:hover .count { color: rgba(255,255,255,0.7); }

/* ===== Footer ===== */
.site-footer {
  background: #0a0a23;
  color: rgba(255,255,255,0.7);
  padding: 56px 0 32px;
  margin-top: 48px;
}
.footer-mission {
  max-width: 640px;
  margin-bottom: 32px;
  font-size: 0.92rem;
  line-height: 1.7;
}
.footer-mission strong { color: #fff; }
.footer-trending {
  margin-bottom: 32px;
}
.footer-trending h4 {
  color: #FEAC32;
  font-size: 0.9rem;
  font-weight: 600;
  margin-bottom: 10px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.footer-trending p {
  font-size: 0.85rem;
  line-height: 1.8;
}
.footer-trending p a { color: rgba(255,255,255,0.7); }
.footer-trending p a:hover { color: #FEAC32; }
.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 12px 20px;
  padding-top: 24px;
  border-top: 1px solid #1b1b36;
}
.footer-links a {
  color: rgba(255,255,255,0.6);
  font-size: 0.82rem;
  text-decoration: none;
  transition: color 0.2s;
}
.footer-links a:hover { color: #FEAC32; }
.footer-bottom {
  margin-top: 24px;
  font-size: 0.78rem;
  color: rgba(255,255,255,0.35);
}

/* ===== Animations ===== */
@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: translateY(0); }
}
.article-card { animation: fadeInUp 0.4s ease both; }
.article-card:nth-child(2) { animation-delay: 0.05s; }
.article-card:nth-child(3) { animation-delay: 0.1s; }
.article-card:nth-child(4) { animation-delay: 0.15s; }
.article-card:nth-child(5) { animation-delay: 0.2s; }
