/* ===== Reset & Base ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; }
body {
  font-family: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  color: #1a1a2e;
  background: #fff;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}
a { color: #002EAD; text-decoration: none; }
a:hover { text-decoration: underline; }
img { max-width: 100%; display: block; }
ul { list-style: none; }
button { cursor: pointer; font-family: inherit; }

/* ===== Utility ===== */
.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); border: 0; }

/* ===== Header ===== */
.site-header {
  background: #0a0a23;
  color: #fff;
  position: sticky;
  top: 0;
  z-index: 100;
}
.header-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 24px;
  max-width: 1200px;
  margin: 0 auto;
  gap: 16px;
}
.logo {
  font-size: 1.25rem;
  font-weight: 700;
  color: #fff;
  white-space: nowrap;
  text-decoration: none;
  letter-spacing: -0.02em;
}
.logo:hover { text-decoration: none; }
.search-bar {
  flex: 1;
  max-width: 420px;
  position: relative;
}
.search-bar input {
  width: 100%;
  padding: 10px 16px 10px 40px;
  border: 2px solid #2a2a4a;
  border-radius: 8px;
  background: #1b1b36;
  color: #fff;
  font-size: 0.9rem;
  outline: none;
  transition: border-color 0.2s;
}
.search-bar input::placeholder { color: #7a7a9e; }
.search-bar input:focus { border-color: #FEAC32; }
.search-bar svg {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  width: 18px;
  height: 18px;
  fill: #7a7a9e;
}
.nav-links {
  display: flex;
  gap: 24px;
  align-items: center;
}
.nav-links a {
  color: #fff;
  font-size: 0.95rem;
  font-weight: 500;
  text-decoration: none;
  transition: color 0.2s;
}
.nav-links a:hover { color: #FEAC32; text-decoration: none; }

/* Hamburger */
.hamburger {
  display: none;
  background: none;
  border: none;
  color: #fff;
  width: 44px;
  height: 44px;
  align-items: center;
  justify-content: center;
}
.hamburger svg { width: 26px; height: 26px; stroke: #fff; fill: none; stroke-width: 2; stroke-linecap: round; }

/* Mobile nav */
.mobile-nav {
  display: none;
  background: #0a0a23;
  border-top: 1px solid #1b1b36;
  padding: 16px 24px;
}
.mobile-nav.open { display: block; }
.mobile-nav a {
  display: block;
  color: #fff;
  font-size: 1rem;
  font-weight: 500;
  padding: 12px 0;
  text-decoration: none;
  border-bottom: 1px solid #1b1b36;
  transition: color 0.2s;
}
.mobile-nav a:last-child { border-bottom: none; }
.mobile-nav a:hover { color: #FEAC32; text-decoration: none; }

@media (max-width: 768px) {
  .nav-links { display: none; }
  .hamburger { display: flex; }
  .search-bar { max-width: 200px; }
  .search-bar input { font-size: 0.8rem; padding: 8px 12px 8px 36px; }
}
@media (max-width: 480px) {
  .search-bar { display: none; }
  .header-top { padding: 12px 16px; }
}

/* ===== Banner ===== */
.banner {
  background: #002EAD;
  color: #fff;
  text-align: center;
  padding: 12px 24px;
  font-size: 0.95rem;
  font-weight: 600;
  letter-spacing: 0.01em;
}
.banner a { color: #FEAC32; font-weight: 700; }

